use crate::{model::*,unit_support::*,bq056 as b};
use crate::jc029_tests::{pass_top,envelope};
fn setup()->(Game,String,String,String){let mut g=game();let observer=field(&mut g,b::ID,0);let target=field(&mut g,"JC125",2);let core=g.make_card("BQ046",0);let id=core.id.clone();g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:Some(core)});fund(&mut g,0,"JC042",1);fund(&mut g,0,"JC056",4);g.regions[0].influence[1]=2;(g,observer,target,id)}
fn enter(g:&mut Game,id:&str){act(g,0,Action{card_id:Some(id.into()),region:Some(0),..Action::new("deploy")});pass_top(g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"trigger");}
#[test]
fn bq056_real_own_core_entry_locks_and_enemy_chooses_one_repression(){let(mut g,_,target,core)=setup();enter(&mut g,&core);choose(&mut g,vec![target.clone()]);pass_top(&mut g);assert_eq!(g.board(&target).unwrap().1.lock_markers,1);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq056-opponent");choose(&mut g,vec!["p2".into()]);assert_eq!(g.pending.as_ref().unwrap().seat,2);let option=g.pending.as_ref().unwrap().choice.options[0].id.clone();choose(&mut g,vec![option]);assert_eq!(g.regions[0].influence[1],1);assert!(g.pending.is_none());restore(&mut g);}
#[test]
fn bq056_core_entry_optional_decline_and_hidden_target_lock(){let(mut g,_,target,core)=setup();g.board_mut(&target).unwrap().face_down=true;enter(&mut g,&core);let mut decline=g.clone();choose(&mut decline,vec![]);assert_eq!(decline.board(&target).unwrap().1.lock_markers,0);choose(&mut g,vec![target.clone()]);pass_top(&mut g);assert_eq!(g.board(&target).unwrap().1.lock_markers,1);}
#[test]
fn bq056_corrupt_entry_receipt_and_waiting_repress_rejected(){let(mut g,_,target,core)=setup();enter(&mut g,&core);let mut bad=g.clone();if let ChoiceResolution::Declare{declaration,..}=&mut bad.pending.as_mut().unwrap().resolution{if let crate::rules::Op::BQ056Lock{entry:Some(e)}=&mut declaration.ability.ops[0]{e.core.card.owner=2;}}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());choose(&mut g,vec![target]);pass_top(&mut g);choose(&mut g,vec!["p2".into()]);for n in 0..2{let mut bad=g.clone();let p=bad.pending.as_mut().unwrap();if n==0{p.seat=0;}else{p.choice.options.clear();}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
#[test]
fn bq056_bonus_only_live_local_enemy_lock_not_friend_or_other_region(){let(mut g,id,target,_)=setup();let c=g.board(&id).unwrap().1.clone();assert_eq!(g.bq056_investigation(&c,0),0);g.board_mut(&target).unwrap().lock_markers=1;assert_eq!(g.bq056_investigation(&c,0),1);g.board_mut(&target).unwrap().face_down=true;assert_eq!(g.bq056_investigation(&c,0),1);g.board_mut(&target).unwrap().controller=1;assert_eq!(g.bq056_investigation(&c,0),0);g.board_mut(&target).unwrap().controller=2;assert_eq!(g.bq056_investigation(&c,1),0);g.board_mut(&id).unwrap().face_down=true;assert_eq!(g.bq056_investigation(g.board(&id).unwrap().1,0),0);}
#[test]
fn bq056_other_core_and_movement_do_not_emit_entry(){let(mut g,_,_,_)=setup();let core=field(&mut g,"BQ046",2);let c=g.board(&core).unwrap().1.clone();let source=g.source_snapshot(&c,Some(0));g.observe_bq056_core_entry(&source);assert!(g.effects.is_empty());g.move_on_board_instance(&core,1);assert!(!g.effects.iter().any(|e|matches!(e,Effect::Declare{declaration}if declaration.ability.key==b::KEY)));}
pub(crate) fn native_case()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(g,_,target,core)=setup();let mut t=Trace::new(g,"bq056-core-entry-lock-repress".into(),560);t.action(0,Action{card_id:Some(core),region:Some(0),..Action::new("deploy")});t.until_pending();t.choose(vec![target]);t.until_pending();t.choose(vec!["p2".into()]);let id=t.room.game.pending.as_ref().unwrap().choice.options[0].id.clone();t.choose(vec![id]);assert!(t.room.game.pending.is_none()&&t.room.game.stack.is_empty());t.value()}

#[test]
fn bq056_stale_or_shielded_target_cancels_lock_and_repression(){for shield in [false,true]{let(mut g,_,target,core)=setup();if shield{g.board_mut(&target).unwrap().shield=1;}enter(&mut g,&core);choose(&mut g,vec![target.clone()]);if !shield{g.remove_dead(&target,RemovalCause::Destroy);}pass_top(&mut g);assert!(g.pending.is_none());assert_eq!(g.regions[0].influence[1],2);if shield{assert_eq!(g.board(&target).unwrap().1.lock_markers,0);assert_eq!(g.board(&target).unwrap().1.shield,0);}restore(&mut g);}}
#[test]
fn bq056_temporary_icon_obeys_first_player_rule(){let(mut g,id,target,_)=setup();g.board_mut(&target).unwrap().lock_markers=1;g.first_team=0;assert_eq!(g.current_icons(g.board(&id).unwrap().1,0).investigation,1);g.first_team=1;assert_eq!(g.current_icons(g.board(&id).unwrap().1,0).investigation,0);}
#[test]
fn bq056_same_team_other_owner_core_and_hidden_observer_do_not_trigger(){for seat in [1,2]{let(mut g,_,_,_)=setup();let id=field(&mut g,"BQ046",seat);g.core_zones.push(crate::core_zone::CoreZone{owner:seat,definition:"BQ046".into(),rest:0,card:None});let c=g.board(&id).unwrap().1.clone();let s=g.source_snapshot(&c,Some(0));g.observe_bq056_core_entry(&s);assert!(g.effects.is_empty());}let(mut g,observer,_,core)=setup();g.board_mut(&observer).unwrap().face_down=true;act(&mut g,0,Action{card_id:Some(core),region:Some(0),..Action::new("deploy")});pass_top(&mut g);assert!(g.pending.is_none());}
#[test]
fn bq056_duplicate_observation_and_transplanted_repress_frame_are_rejected(){let(mut g,_,target,core)=setup();enter(&mut g,&core);choose(&mut g,vec![target]);let mut bad=g.clone();bad.stack.push(bad.stack.last().unwrap().clone());assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());pass_top(&mut g);let mut bad=g.clone();if let ChoiceResolution::Frame{frame,..}=&mut bad.pending.as_mut().unwrap().resolution{frame.ability_key="unrelated".into();frame.steps.clear();}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}

#[test]
fn bq056_locked_attached_dual_type_character_counts_but_ordinary_attachment_does_not(){let(mut g,id,_,_)=setup();let host=field(&mut g,"JC029",2);let mut bat=g.make_card("BQ026",2);bat.lock_markers=1;let bat_id=bat.id.clone();g.attachments.push(Attachment{card:bat,host_id:host.clone()});restore(&mut g);assert_eq!(g.current_icons(g.board(&id).unwrap().1,0).investigation,1);g.attachments.clear();let mut ordinary=g.make_card("JC073",2);ordinary.lock_markers=1;g.attachments.push(Attachment{card:ordinary,host_id:host});assert_eq!(g.current_icons(g.board(&id).unwrap().1,0).investigation,0);assert!(g.board(&bat_id).is_none());}
